package main

import (
	"encoding/hex"
	"flag"
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"io"
	"math"
	"net/http"
	"os"
	"strings"
)

const version = "1.3.2"

const credits = `   ___  _____  ____
  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2

CONTRIBUTORS:

  > @disq - https://github.com/disq
      + Original code for image transparency support.

  > @timob - https://github.com/timob
      + Fix for ANSIpixel type: use 8bit color component for output.

  > @HongjiangHuang - https://github.com/HongjiangHuang
      + Original code for image download support.

  > @brutestack - https://github.com/brutestack
      + Color support for Windows (Command Prompt & PowerShell).
      + Original code for disable background color in dithering mode.
      + Original code for output Go code to 'fmt.Print()' the image.

  > @diamondburned - https://github.com/diamondburned
      + NewFromImage() & NewScaledFromImage() for ANSImage API.

  > @MichaelMure - https://github.com/MichaelMure
      + More conventional 'go.mod' file at repository.

  > @Calinou - https://github.com/Calinou
      + Use HTTPS URLs everywhere.
      + Other awesome contributions.

  > @danirod - https://github.com/danirod
  > @Xpktro - https://github.com/Xpktro
      + Moral support.
`

func main() {
	var (
		showVersion = flag.Bool("version", false, "show PIXterm version")
		showCredits = flag.Bool("credits", false, "show some love to contributors <3")
		ditherMode  = flag.Int("d", 0, "dithering mode")
		goCode      = flag.Bool("go", false, "output Go code to 'fmt.Print()' the image")
		matteHex    = flag.String("m", "000000", "matte color for transparency or background")
		noBg        = flag.Bool("nobg", false, "disable background color")
		scaleMethod = flag.Int("s", 0, "scale method")
		termRows    = flag.Int("tr", 24, "terminal rows")
		termCols    = flag.Int("tc", 80, "terminal columns")
	)

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "   ___  _____  ____\n")
		fmt.Fprintf(os.Stderr, "  / _ \\/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau\n")
		fmt.Fprintf(os.Stderr, " / ___// /_>  </ __/ -_) __/  ' \\ https://github.com/eliukblau/pixterm\n")
		fmt.Fprintf(os.Stderr, "/_/  /___/_/|_|\\__/\__/_/ /_/_/_/                %s\n\n", version)
		fmt.Fprintf(os.Stderr, "USAGE:\n\n")
		fmt.Fprintf(os.Stderr, "  %s [options] image/url\n\n", os.Args[0])
		fmt.Fprintf(os.Stderr, "  Supported image formats: JPEG, PNG, GIF, BMP, TIFF, WebP.\n")
		fmt.Fprintf(os.Stderr, "  Supported URL protocols: HTTP, HTTPS.\n\n")
		fmt.Fprintf(os.Stderr, "OPTIONS:\n\n")
		flag.PrintDefaults()
		fmt.Fprintf(os.Stderr, "  -help\n\tprints this message :D LOL\n")
	}

	flag.Parse()

	if *showVersion {
		fmt.Println(version)
		return
	}

	if *showCredits {
		fmt.Print(credits)
		return
	}

	if flag.NArg() < 1 {
		flag.Usage()
		os.Exit(2)
	}

	imagePath := flag.Arg(0)
	var imgReader io.ReadCloser
	if strings.HasPrefix(imagePath, "http://") || strings.HasPrefix(imagePath, "https://") {
		resp, err := http.Get(imagePath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error fetching image: %v\n", err)
			os.Exit(1)
		}
		imgReader = resp.Body
	} else {
		f, err := os.Open(imagePath)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening image: %v\n", err)
			os.Exit(1)
		}
		imgReader = f
	}
	defer imgReader.Close()

	img, _, err := image.Decode(imgReader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error decoding image: %v\n", err)
		os.Exit(1)
	}

	matteColor, err := parseHexColor(*matteHex)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Invalid matte color: %v\n", err)
		os.Exit(1)
	}

	// Calculate target pixel dimensions
	var targetW, targetH int
	tw, th := *termCols, *termRows
	if tw < 2 { tw = 80 }
	if th < 2 { th = 24 }

	ph := th
	if *ditherMode == 0 {
		ph = th * 2
	}
	pw := tw

	sw, sh := img.Bounds().Dx(), img.Bounds().Dy()

	switch *scaleMethod {
	case 0: // resize
		targetW, targetH = pw, ph
	case 1: // fill
		ratio := math.Max(float64(pw)/float64(sw), float64(ph)/float64(sh))
		targetW = int(math.Round(float64(sw) * ratio))
		targetH = int(math.Round(float64(sh) * ratio))
	case 2: // fit
		ratio := math.Min(float64(pw)/float64(sw), float64(ph)/float64(sh))
		targetW = int(math.Round(float64(sw) * ratio))
		targetH = int(math.Round(float64(sh) * ratio))
	default:
		targetW, targetH = pw, ph
	}

	scaledImg := scaleImage(img, targetW, targetH)

	// Crop if necessary (for fill method)
	if *scaleMethod == 1 {
		scaledImg = cropImage(scaledImg, pw, ph)
	}

	render(scaledImg, *ditherMode, matteColor, *noBg, *goCode)
}

func parseHexColor(s string) (color.RGBA, error) {
	if strings.HasPrefix(s, "#") {
		s = s[1:]
	}
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != 3 {
		return color.RGBA{0, 0, 0, 255}, err
	}
	return color.RGBA{b[0], b[1], b[2], 255}, nil
}

func scaleImage(img image.Image, w, h int) image.Image {
	srcBounds := img.Bounds()
	srcW, srcH := srcBounds.Dx(), srcBounds.Dy()
	dst := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			// Nearest neighbor for now to be safe, or bilinear
			srcX := int(float64(x) * float64(srcW) / float64(w))
			srcY := int(float64(y) * float64(srcH) / float64(h))
			dst.Set(x, y, img.At(srcBounds.Min.X+srcX, srcBounds.Min.Y+srcY))
		}
	}
	return dst
}

func cropImage(img image.Image, w, h int) image.Image {
	bounds := img.Bounds()
	dx := (bounds.Dx() - w) / 2
	dy := (bounds.Dy() - h) / 2
	if dx < 0 { dx = 0 }
	if dy < 0 { dy = 0 }

	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			dst.Set(x, y, img.At(bounds.Min.X+dx+x, bounds.Min.Y+dy+y))
		}
	}
	return dst
}

func render(img image.Image, ditherMode int, matte color.RGBA, noBg bool, goCode bool) {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	if ditherMode == 0 {
		for y := 0; y < h; y += 2 {
			var line strings.Builder
			for x := 0; x < w; x++ {
				c1 := blend(img.At(bounds.Min.X+x, bounds.Min.Y+y), matte)
				var c2 color.RGBA
				if y+1 < h {
					c2 = blend(img.At(bounds.Min.X+x, bounds.Min.Y+y+1), matte)
				} else {
					c2 = matte
				}
				line.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B))
			}
			line.WriteString("\x1b[0m")
			if goCode {
				output := strings.ReplaceAll(line.String(), "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\n\")\n", output)
			} else {
				fmt.Println(line.String())
			}
		}
	} else {
		var chars string
		if ditherMode == 1 {
			chars = " ░▒▓█"
		} else {
			chars = " .:-=+*#%@$" // Wait, I found 11 chars earlier
			chars = " .:;+=xX$&#"
		}

		for y := 0; y < h; y++ {
			var line strings.Builder
			for x := 0; x < w; x++ {
				c := blend(img.At(bounds.Min.X+x, bounds.Min.Y+y), matte)
				intensity := (0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)) / 255.0
				idx := int(intensity * float64(len(chars)))
				if idx >= len(chars) { idx = len(chars) - 1 }
				char := chars[idx:idx+1]
				if ditherMode == 1 && idx > 0 {
					// UTF-8 characters
					runes := []rune(" ░▒▓█")
					char = string(runes[idx])
				}

				if !noBg {
					line.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm", matte.R, matte.G, matte.B))
				}
				line.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s", c.R, c.G, c.B, char))
			}
			line.WriteString("\x1b[0m")
			if goCode {
				output := strings.ReplaceAll(line.String(), "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\n\")\n", output)
			} else {
				fmt.Println(line.String())
			}
		}
	}
}

func blend(c color.Color, matte color.RGBA) color.RGBA {
	r, g, b, a := c.RGBA()
	// Go's RGBA() returns alpha-premultiplied values in range [0, 65535]
	alpha := float64(a) / 65535.0
	return color.RGBA{
		R: uint8((float64(r)/65535.0*(1-0) + float64(matte.R)/255.0*(1-alpha)) * 255.0),
		G: uint8((float64(g)/65535.0*(1-0) + float64(matte.G)/255.0*(1-alpha)) * 255.0),
		B: uint8((float64(b)/65535.0*(1-0) + float64(matte.B)/255.0*(1-alpha)) * 255.0),
		A: 255,
	}
}
