func parseHexColor(s string) (color.RGBA, error) {
	if strings.HasPrefix(s, "#") {
		s = s[1:]
	}
	b, err := hex.DecodeString(s)
	if err != nil || len(b) != 3 {
		return color.RGBA{0, 0, 0, 255}, err
	}
	return color.RGBA{b[0], b[1], b[2], 255}, nil
}

func scaleImage(img image.Image, w, h int) image.Image {
	srcBounds := img.Bounds()
	srcW, srcH := srcBounds.Dx(), srcBounds.Dy()
	dst := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			fx := (float64(x) + 0.5) * float64(srcW) / float64(w) - 0.5
			fy := (float64(y) + 0.5) * float64(srcH) / float64(h) - 0.5
			ix := int(math.Floor(fx))
			iy := int(math.Floor(fy))
			tx := fx - float64(ix)
			ty := fy - float64(iy)
			c00 := getP(img, srcBounds, ix, iy)
			c10 := getP(img, srcBounds, ix+1, iy)
			c01 := getP(img, srcBounds, ix, iy+1)
			c11 := getP(img, srcBounds, ix+1, iy+1)
			r := (1-tx)*(1-ty)*float64(c00.R) + tx*(1-ty)*float64(c10.R) + (1-tx)*ty*float64(c01.R) + tx*ty*float64(c11.R)
