					c2 = blend(img.At(bounds.Min.X+x, bounds.Min.Y+y+1), matte)
				} else {
					c2 = matte
				}
				line.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B))
			}
			line.WriteString("\x1b[0m")
			if goCode {
				output := strings.ReplaceAll(line.String(), "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\n\")\n", output)
			} else {
				fmt.Println(line.String())
			}
		}
	} else {
		var chars []rune
		if ditherMode == 1 {
			chars = []rune(" ░▒▓█")
		} else {
			chars = []rune(" .:;+=xX$&#")
		}
		for y := 0; y < h; y++ {
			var line strings.Builder
			for x := 0; x < w; x++ {
				c := blend(img.At(bounds.Min.X+x, bounds.Min.Y+y), matte)
				intensity := (0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)) / 255.0
