			fy := (float64(y) + 0.5) * float64(srcH) / float64(h) - 0.5
			ix := int(math.Floor(fx))
			iy := int(math.Floor(fy))
			tx := fx - float64(ix)
			ty := fy - float64(iy)
			c00 := getP(img, srcBounds, ix, iy)
			c10 := getP(img, srcBounds, ix+1, iy)
			c01 := getP(img, srcBounds, ix, iy+1)
			c11 := getP(img, srcBounds, ix+1, iy+1)
			r := (1-tx)*(1-ty)*float64(c00.R) + tx*(1-ty)*float64(c10.R) + (1-tx)*ty*float64(c01.R) + tx*ty*float64(c11.R)
			g := (1-tx)*(1-ty)*float64(c00.G) + tx*(1-ty)*float64(c10.G) + (1-tx)*ty*float64(c01.G) + tx*ty*float64(c11.G)
			b := (1-tx)*(1-ty)*float64(c00.B) + tx*(1-ty)*float64(c10.B) + (1-tx)*ty*float64(c01.B) + tx*ty*float64(c11.B)
			a := (1-tx)*(1-ty)*float64(c00.A) + tx*(1-ty)*float64(c10.A) + (1-tx)*ty*float64(c01.A) + tx*ty*float64(c11.A)
			dst.Set(x, y, color.RGBA{uint8(r), uint8(g), uint8(b), uint8(a)})
		}
	}
	return dst
