func getP(img image.Image, bounds image.Rectangle, x, y int) color.RGBA {
	if x < 0 { x = 0 }
	if y < 0 { y = 0 }
	if x >= bounds.Dx() { x = bounds.Dx() - 1 }
	if y >= bounds.Dy() { y = bounds.Dy() - 1 }
	r, g, b, a := img.At(bounds.Min.X+x, bounds.Min.Y+y).RGBA()
	return color.RGBA{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8), uint8(a >> 8)}
}

func cropImage(img image.Image, w, h int) image.Image {
	bounds := img.Bounds()
	dx := (bounds.Dx() - w) / 2
	dy := (bounds.Dy() - h) / 2
	if dx < 0 { dx = 0 }
	if dy < 0 { dy = 0 }
	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			dst.Set(x, y, img.At(bounds.Min.X+dx+x, bounds.Min.Y+dy+y))
		}
	}
	return dst
}

func render(img image.Image, ditherMode int, matte color.RGBA, noBg bool, goCode bool) {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()
	if ditherMode == 0 {
		for y := 0; y < h; y += 2 {
			var line strings.Builder
			for x := 0; x < w; x++ {
				c1 := blend(img.At(bounds.Min.X+x, bounds.Min.Y+y), matte)
				var c2 color.RGBA
				if y+1 < h {
					c2 = blend(img.At(bounds.Min.X+x, bounds.Min.Y+y+1), matte)
				} else {
					c2 = matte
				}
				line.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B))
			}
			line.WriteString("\x1b[0m")
			if goCode {
				output := strings.ReplaceAll(line.String(), "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\n\")\n", output)
			} else {
				fmt.Println(line.String())
			}
		}
	} else {
		var chars []rune
		if ditherMode == 1 {
			chars = []rune(" ░▒▓█")
		} else {
			chars = []rune(" .:;+=xX$&#")
		}
		for y := 0; y < h; y++ {
			var line strings.Builder
			for x := 0; x < w; x++ {
				c := blend(img.At(bounds.Min.X+x, bounds.Min.Y+y), matte)
				intensity := (0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)) / 255.0
				idx := int(intensity * float64(len(chars)))
				if idx >= len(chars) { idx = len(chars) - 1 }
				char := string(chars[idx])
				if !noBg {
					line.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm", matte.R, matte.G, matte.B))
				}
				line.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s", c.R, c.G, c.B, char))
			}
			line.WriteString("\x1b[0m")
			if goCode {
				output := strings.ReplaceAll(line.String(), "\x1b", "\\033")
				fmt.Printf("fmt.Print(\"%s\\n\")\n", output)
			} else {
				fmt.Println(line.String())
			}
		}
	}
}

func blend(c color.Color, matte color.RGBA) color.RGBA {
	r, g, b, a := c.RGBA()
	alpha := float64(a) / 65535.0
	return color.RGBA{
		R: uint8( (float64(r)/65535.0 + (float64(matte.R)/255.0)*(1-alpha)) * 255.0 ),
		G: uint8( (float64(g)/65535.0 + (float64(matte.G)/255.0)*(1-alpha)) * 255.0 ),
		B: uint8( (float64(b)/65535.0 + (float64(matte.B)/255.0)*(1-alpha)) * 255.0 ),
		A: 255,
	}
}
